    index_model_type character varying,
    monitor_type character varying,
    is_standard integer,
    data_range character varying,
    contain_time character varying,
    is_public integer,
    wf_id bigint,
    is_unit integer,
    sort_index integer,
    dead_enable smallint,
    jump_enable smallint,
    jump_fix_range integer,
    jump_threshold numeric(20,2),
    not_greater_enable integer,
    compare_target_iec character varying,
    fix_effective_min numeric(20,2),
    fix_effective_max numeric(20,2),
    create_time timestamp(6) without time zone DEFAULT now(),
    update_time timestamp(6) without time zone
);


ALTER TABLE dim.dim_index_model OWNER TO powerforecast;

--
-- Name: COLUMN dim_index_model.id; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.id IS '雪花id';


--
-- Name: COLUMN dim_index_model.statistic_type; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.statistic_type IS '0统计配置，1三方数据清洗配置';


--
-- Name: COLUMN dim_index_model.name; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.name IS '指标模型名称';


--
