--

COMMENT ON COLUMN dim.dim_index_model.calculation_method IS '统计转换方式（来自字典表）: calculation_empty 无计算, calculation_arithmetic_mean 算法求平均';


--
-- Name: COLUMN dim_index_model.single_index_method; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.single_index_method IS '单指标转换方式（0无计算，1应用系数与加值，2值映射）';


--
-- Name: COLUMN dim_index_model.pa; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.pa IS '系数';


--
-- Name: COLUMN dim_index_model.pb; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.pb IS '偏移量';


--
-- Name: COLUMN dim_index_model.value_mapping; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.value_mapping IS '指标值映射关系:condition：判断规则, statement_value：判断值, target：映射目标值';


--
-- Name: COLUMN dim_index_model.target_unit; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.target_unit IS '目标单位';


--
-- Name: COLUMN dim_index_model.index_model_iec; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.index_model_iec IS '目标指标key';


--
-- Name: COLUMN dim_index_model.index_model_type; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.index_model_type IS 'ai，di，do';


--
-- Name: COLUMN dim_index_model.monitor_type; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.monitor_type IS '设备类型';


--
-- Name: COLUMN dim_index_model.is_standard; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.is_standard IS '是否标量';


