--

COMMENT ON COLUMN dim.dim_index_model.data_range IS '源数据间隔 7s，1min，5min';


--
-- Name: COLUMN dim_index_model.contain_time; Type: COMMENT; Schema: dim; Owner: powerforecast
--

COMMENT ON COLUMN dim.dim_index_model.contain_time IS '要统计出哪类数据，1分钟,5分钟,15分钟';


