-- Name: COLUMN ods_fact_wf_data_1min.di_value; Type: COMMENT; Schema: ods; Owner: powerforecast
--

COMMENT ON COLUMN ods.ods_fact_wf_data_1min.di_value IS 'Divalue 遥信数据';


